mapper.select:
SELECT DATE_FORMAT(o.paid_at, '%Y-%m-%d') AS date, SUM(oi.price * oi.quantity) AS sales, COUNT(DISTINCT o.id) AS orderCount FROM `cors`.`orders` o JOIN `cors`.`order_items` oi ON o.id = oi.order_id WHERE oi.shop_id = #{shopId}
AND o.paid_at >= #{startDate} AND o.paid_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND o.status = 'PAID' AND oi.status = '4' GROUP BY DATE_FORMAT(o.paid_at, '%Y-%m-%d') ORDER BY date ASC

SELECT DATE_FORMAT(o.paid_at, '%Y-%m') AS date, SUM(oi.price * oi.quantity) AS sales, COUNT(DISTINCT o.id) AS orderCount FROM `cors`.`orders` o JOIN `cors`.`order_items` oi ON o.id = oi.order_id WHERE oi.shop_id = #{shopId}
AND o.paid_at >= #{startDate} AND o.paid_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND o.status = 'PAID' AND oi.status = '4' GROUP BY DATE_FORMAT(o.paid_at, '%Y-%m') ORDER BY date ASC

SELECT IFNULL(SUM(oi.price * oi.quantity), 0) FROM `cors`.`orders` o JOIN `cors`.`order_items` oi ON o.id = oi.order_id WHERE oi.shop_id = #{shopId}
AND o.paid_at >= #{startDate} AND o.paid_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND o.status = 'PAID' AND oi.status = '4'

SELECT COUNT(DISTINCT o.id) FROM `cors`.`orders` o JOIN `cors`.`order_items` oi ON o.id = oi.order_id WHERE oi.shop_id = #{shopId}
AND o.paid_at >= #{startDate} AND o.paid_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND o.status = 'PAID' AND oi.status = '4'

SELECT si.item_name AS productName, SUM(total_sales) AS totalSales, SUM(total_quantity) AS totalQuantity, (SELECT `img`.`image_path` FROM `cors`.`shop_item_images` AS `img` WHERE `img`.`product_id` = `si`.`id` ORDER BY `img`.`id` ASC LIMIT 1) AS `imagePath` FROM ( -- 1. 일반 주문 매출 SELECT oi.item_id, SUM(oi.price * oi.quantity) AS total_sales, SUM(oi.quantity) AS total_quantity FROM `cors`.`order_items` oi JOIN `cors`.`orders` o ON oi.order_id = o.id WHERE oi.shop_id = #{shopId} AND o.status = 'PAID' AND oi.status = '4' GROUP BY oi.item_id
UNION ALL
-- 2. 예약 거래 완료 매출 SELECT ri.item_id, SUM(si.price) AS total_sales, COUNT(ri.id) AS total_quantity FROM `cors`.`reservations` r JOIN `cors`.`reservation_items` ri ON r.id = ri.reservation_id JOIN `cors`.`shop_items` si ON ri.item_id = si.id WHERE r.shop_id = #{shopId} AND r.status = '완료' GROUP BY ri.item_id ) AS combined_sales JOIN `cors`.`shop_items` si ON combined_sales.item_id = si.id GROUP BY si.id, si.item_name ORDER BY totalSales DESC LIMIT #{limit}

SELECT COUNT(DISTINCT r.id)
FROM `cors`.`reservations` r
WHERE r.shop_id = #{shopId}
  AND r.status = '완료'

  AND r.updated_at >= #{startDate}
  AND r.updated_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
